//! Codegen binary for the shared theme manifest.
//!
//! Reads `crates/mew-tui/resources/theme_manifest.json` and emits:
//! - `mew-web-ui/src/generated-themes.css`
//! - `crates/mew-tui/src/theme_generated.rs`
//! - `crates/ratatui-mdstream/resources/theme.tmTheme`
//!
//! Run with `--check` to verify that the generated files are up-to-date.

use std::collections::HashMap;
use std::path::PathBuf;

const MANIFEST_PATH: &str = "crates/mew-tui/resources/theme_manifest.json";
const CSS_OUT: &str = "mew-web-ui/src/generated-themes.css";
const RUST_OUT: &str = "crates/mew-tui/src/theme_generated.rs";
const TMTHEME_OUT: &str = "crates/ratatui-mdstream/resources/theme.tmTheme";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let check = std::env::args().any(|a| a == "--check");
    let root = find_project_root()?;
    let manifest_path = root.join(MANIFEST_PATH);
    let css_out = root.join(CSS_OUT);
    let rust_out = root.join(RUST_OUT);
    let tmtheme_out = root.join(TMTHEME_OUT);

    let manifest: Manifest = serde_json::from_str(&std::fs::read_to_string(&manifest_path)?)?;

    let css = generate_css(&manifest);
    let rust = generate_rust(&manifest);
    let tmtheme = generate_tmtheme(&manifest, "dark");

    if check {
        let css_existing = std::fs::read_to_string(&css_out).unwrap_or_default();
        let rust_existing = std::fs::read_to_string(&rust_out).unwrap_or_default();
        let tmtheme_existing = std::fs::read_to_string(&tmtheme_out).unwrap_or_default();

        if css != css_existing || rust != rust_existing || tmtheme != tmtheme_existing {
            eprintln!("error: generated theme files are out of date");
            eprintln!("       run `cargo run -p mew-tui --bin theme_codegen` to regenerate");
            std::process::exit(1);
        }
        println!("generated theme files are up-to-date");
        return Ok(());
    }

    std::fs::create_dir_all(css_out.parent().unwrap())?;
    std::fs::create_dir_all(rust_out.parent().unwrap())?;
    std::fs::create_dir_all(tmtheme_out.parent().unwrap())?;

    std::fs::write(&css_out, css)?;
    std::fs::write(&rust_out, rust)?;
    std::fs::write(&tmtheme_out, tmtheme)?;

    println!("wrote {}", css_out.display());
    println!("wrote {}", rust_out.display());
    println!("wrote {}", tmtheme_out.display());
    Ok(())
}

fn find_project_root() -> Result<PathBuf, Box<dyn std::error::Error>> {
    let mut dir = std::env::current_dir()?;
    loop {
        if dir.join("Cargo.toml").exists() && dir.join(MANIFEST_PATH).exists() {
            return Ok(dir);
        }
        if !dir.pop() {
            return Err("could not find project root".into());
        }
    }
}

#[derive(Debug, serde::Deserialize)]
struct Manifest {
    #[allow(dead_code)]
    version: u32,
    tokens: HashMap<String, String>,
    themes: HashMap<String, ThemeDef>,
}

#[derive(Debug, serde::Deserialize)]
struct ThemeDef {
    #[allow(dead_code)]
    mode: String,
    #[serde(default)]
    #[allow(dead_code)]
    base: Option<String>,
    #[serde(default)]
    tokens: HashMap<String, String>,
}

fn resolve_table(raw: &HashMap<String, String>) -> Result<HashMap<String, String>, String> {
    let mut resolved = HashMap::new();
    for key in raw.keys() {
        let value = resolve_key(raw, key, &mut std::collections::HashSet::new(), 0)?;
        resolved.insert(key.clone(), value);
    }
    Ok(resolved)
}

fn resolve_key(
    raw: &HashMap<String, String>,
    key: &str,
    stack: &mut std::collections::HashSet<String>,
    depth: usize,
) -> Result<String, String> {
    const MAX_DEPTH: usize = 32;
    if depth > MAX_DEPTH {
        return Err(format!("alias cycle or too deep: {key}"));
    }
    let value = raw
        .get(key)
        .ok_or_else(|| format!("unknown token: {key}"))?;
    if let Some(alias) = value.strip_prefix('@') {
        if !stack.insert(alias.to_string()) {
            return Err(format!("alias cycle: {alias}"));
        }
        let resolved = resolve_key(raw, alias, stack, depth + 1)?;
        stack.remove(alias);
        Ok(resolved)
    } else {
        Ok(value.clone())
    }
}

fn token_to_css_var(key: &str) -> String {
    format!("--{}", key.replace(['.', '_'], "-"))
}

fn generate_css(manifest: &Manifest) -> String {
    let mut out = String::new();
    out.push_str("/* Generated by theme_codegen. Do not edit by hand. */\n");

    // Sort themes so output is deterministic.
    let mut theme_ids: Vec<&String> = manifest.themes.keys().collect();
    theme_ids.sort();

    for id in theme_ids {
        // dark and light are shadcn fallback bases, not selectable web themes.
        if id == "dark" || id == "light" {
            continue;
        }
        let def = &manifest.themes[id];
        let mut merged = manifest.tokens.clone();
        for (k, v) in &def.tokens {
            merged.insert(k.clone(), v.clone());
        }
        let resolved = match resolve_table(&merged) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("warning: failed to resolve theme {}: {}", id, e);
                continue;
            }
        };

        out.push_str(&format!("\n[data-theme=\"{}\"] {{\n", id));
        let mut keys: Vec<&String> = resolved.keys().collect();
        keys.sort();
        for key in keys {
            // Skip CSS-only metadata tokens.
            if key.starts_with('_') {
                continue;
            }
            let value = &resolved[key];
            // Only emit color and dimension tokens that are useful as CSS variables.
            // Skip internal tokens that have no web consumer for now.
            if key.starts_with("terminal.")
                || key.starts_with("pill.")
                || key.starts_with("syntax.")
            {
                continue;
            }
            out.push_str(&format!("  {}: {};\n", token_to_css_var(key), value));
        }
        out.push_str("}\n");
    }
    out
}

fn generate_rust(manifest: &Manifest) -> String {
    let mut out = String::new();
    out.push_str("//! Generated theme data. Do not edit by hand.\n\n");
    out.push_str("use std::collections::HashMap;\n\n");
    out.push_str("/// The base token table from the manifest.\npub const BASE_TOKENS: &[(&str, &str)] = &[\n");
    let mut base_keys: Vec<&String> = manifest.tokens.keys().collect();
    base_keys.sort();
    for k in base_keys {
        // Skip CSS-only metadata tokens (e.g. radius notes).
        if k.starts_with('_') {
            continue;
        }
        out.push_str(&format!("    (\"{}\", \"{}\"),\n", k, manifest.tokens[k]));
    }
    out.push_str("];\n\n");

    let mut theme_ids: Vec<&String> = manifest.themes.keys().collect();
    theme_ids.sort();
    out.push_str("/// Per-theme sparse overrides.\npub const THEME_OVERRIDES: &[(&str, &[(&str, &str)])] = &[\n");
    for id in theme_ids {
        let def = &manifest.themes[id];
        out.push_str(&format!("    (\"{}\", &[\n", id));
        let mut keys: Vec<&String> = def.tokens.keys().collect();
        keys.sort();
        for k in keys {
            out.push_str(&format!("        (\"{}\", \"{}\"),\n", k, def.tokens[k]));
        }
        out.push_str("    ]),\n");
    }
    out.push_str("];\n\n");

    out.push_str("/// Build a resolved token table for a built-in theme.\npub fn resolved_table(name: &str) -> Option<HashMap<String, String>> {\n");
    out.push_str("    let mut table: HashMap<String, String> = BASE_TOKENS.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect();\n");
    out.push_str("    let overrides = THEME_OVERRIDES.iter().find(|(n, _)| *n == name)?.1;\n");
    out.push_str("    for (k, v) in overrides {\n");
    out.push_str("        table.insert(k.to_string(), v.to_string());\n");
    out.push_str("    }\n");
    out.push_str("    Some(resolve_aliases(table))\n");
    out.push_str("}\n\n");

    out.push_str(
        "fn resolve_aliases(mut raw: HashMap<String, String>) -> HashMap<String, String> {\n",
    );
    out.push_str("    let keys: Vec<String> = raw.keys().cloned().collect();\n");
    out.push_str("    for key in keys {\n");
    out.push_str("        let mut seen = std::collections::HashSet::new();\n");
    out.push_str("        let mut cur = raw[&key].clone();\n");
    out.push_str("        while cur.starts_with('@') {\n");
    out.push_str("            let alias = &cur[1..];\n");
    out.push_str("            if !seen.insert(alias.to_string()) { break; }\n");
    out.push_str("            cur = raw.get(alias).cloned().unwrap_or(cur);\n");
    out.push_str("        }\n");
    out.push_str("        raw.insert(key, cur);\n");
    out.push_str("    }\n");
    out.push_str("    raw\n");
    out.push_str("}\n");
    out
}

fn generate_tmtheme(manifest: &Manifest, theme_name: &str) -> String {
    let def = match manifest.themes.get(theme_name) {
        Some(d) => d,
        None => {
            eprintln!(
                "warning: theme {} not found for tmTheme; using base",
                theme_name
            );
            return generate_tmtheme_from_table(&manifest.tokens);
        }
    };
    let mut merged = manifest.tokens.clone();
    for (k, v) in &def.tokens {
        merged.insert(k.clone(), v.clone());
    }
    match resolve_table(&merged) {
        Ok(resolved) => generate_tmtheme_from_table(&resolved),
        Err(e) => {
            eprintln!("warning: failed to resolve tmTheme: {}", e);
            generate_tmtheme_from_table(&manifest.tokens)
        }
    }
}

fn generate_tmtheme_from_table(resolved: &HashMap<String, String>) -> String {
    let bg = resolved
        .get("background")
        .cloned()
        .unwrap_or_else(|| "#1e1e21".into());
    let fg = resolved
        .get("foreground")
        .cloned()
        .unwrap_or_else(|| "#ffffff".into());

    let scopes: &[(&str, &str)] = &[
        ("comment", "syntax.comment"),
        ("string", "syntax.string"),
        ("keyword", "syntax.keyword"),
        ("entity.name.function, support.function", "syntax.function"),
        ("constant.numeric", "syntax.number"),
        ("entity.name.type, storage.type", "syntax.type"),
        ("variable", "syntax.variable"),
        ("keyword.operator", "syntax.operator"),
        ("constant", "syntax.constant"),
    ];

    let mut out = String::new();
    out.push_str(r#"<?xml version="1.0" encoding="UTF-8"?>"#);
    out.push('\n');
    out.push_str(
        r#"<!DOCTYPE plist SYSTEM "file://localhost/System/Library/DTDs/PropertyList.dtd">"#,
    );
    out.push('\n');
    out.push_str(r#"<plist version="1.0">"#);
    out.push('\n');
    out.push_str("<dict>\n");
    out.push_str("  <key>name</key>\n");
    out.push_str("  <string>mew generated</string>\n");
    out.push_str("  <key>settings</key>\n");
    out.push_str("  <array>\n");

    // Global settings
    out.push_str("    <dict>\n");
    out.push_str("      <key>settings</key>\n");
    out.push_str("      <dict>\n");
    out.push_str(&format!(
        "        <key>background</key><string>{}</string>\n",
        bg
    ));
    out.push_str(&format!(
        "        <key>foreground</key><string>{}</string>\n",
        fg
    ));
    out.push_str("      </dict>\n");
    out.push_str("    </dict>\n");

    for (scope, token) in scopes {
        let color = resolved.get(*token).cloned().unwrap_or_else(|| fg.clone());
        out.push_str("    <dict>\n");
        out.push_str(&format!(
            "      <key>name</key><string>{}</string>\n",
            token
        ));
        out.push_str(&format!(
            "      <key>scope</key><string>{}</string>\n",
            scope
        ));
        out.push_str("      <key>settings</key>\n");
        out.push_str("      <dict>\n");
        out.push_str(&format!(
            "        <key>foreground</key><string>{}</string>\n",
            color
        ));
        out.push_str("      </dict>\n");
        out.push_str("    </dict>\n");
    }

    out.push_str("  </array>\n");
    out.push_str("</dict>\n");
    out.push_str("</plist>\n");
    out
}
